//function mouse_over(imageNum)
function mouse_over(imageNum)
{
  if (has_loaded==1)
  {  
    var iNum;
    var i;
    var name;
    var iname;
    name = "status"+imageNum;
    window.status = _eval(name);

    if (do__javascript == 0)
    {
      return true;
    } //if (do__javascript == 0)

    iNum = parseInt(imageNum);

    for (i = 4; i <12; i=i+1)
    {
      name="image" +i;

      if (i== iNum)
      {
        iname="overImage" +i+".src";
      }
      else
      {
        iname="outImage" +i+".src";
      } //if (i== iNum)

      document[name].src=_eval(iname);
    } //for (i = 5; i <12; i=i+1)
  } //if (has_loaded==1)
  return true; 
} //function mouse_over(imageNum)

//function mouse_out(imageNum)
function mouse_out(imageNum)
{
  if (has_loaded==1)
  {
    var name;
    var iname;
    window.status = " ";

    if (do__javascript == 0)
    {
      return true;
    } //if (do__javascript == 0)

    name = "image"+imageNum;
    iname = "outImage"+imageNum+".src";
    document [name].src = _eval(iname);
  } //if (has_loaded==1)

  return true;
} //function mouse_out(imageNum)

